MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

_VALID_TIERS = frozenset(TIER_FEES)
_VALID_METHODS = frozenset({"card", "transfer"})


def _invalid(message: str) -> dict:
    return {"ok": False, "error": message}


def _validate_common(member: dict, payment: dict):
    """Shared validation. Returns an error dict, or None if input is valid."""
    if "id" not in member or "status" not in member or "tier" not in member:
        return _invalid("missing member field")
    if "amount" not in payment or "method" not in payment:
        return _invalid("missing payment field")
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return _invalid("bad member id")
    if member["tier"] not in _VALID_TIERS:
        return _invalid("unknown tier")
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return _invalid("bad amount")
    if payment["method"] not in _VALID_METHODS:
        return _invalid("unsupported method")
    return None


def _receipt(method: str, member_id: str, status: str, fee: int) -> str:
    return f"{method}:{member_id}:{status}:{fee}"


def _renewed(member: dict, payment: dict, fee: int, status: str) -> dict:
    return {
        "ok": True,
        "status": status,
        "fee": fee,
        "receipt": _receipt(payment["method"], member["id"], status, fee),
    }


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return _invalid("malformed input")

    member = raw_member
    payment = raw_payment

    if "status" not in member:
        return _invalid("missing member field")
    status = member["status"]

    if status == "banned":
        return _invalid("member banned")

    if status not in ("active", "lapsed", "suspended"):
        return _invalid("unknown status")

    error = _validate_common(member, payment)
    if error is not None:
        return error

    if status == "active":
        fee = TIER_FEES[member["tier"]]
        out_status = "renewed"
    elif status == "lapsed":
        if "expired_days" not in member or not isinstance(member["expired_days"], int) or member["expired_days"] < 0:
            return _invalid("bad expiry")
        if member["expired_days"] <= GRACE_DAYS:
            fee = TIER_FEES[member["tier"]] + LATE_FEE
            out_status = "renewed"
        else:
            fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
            out_status = "reinstated"
    else:  # suspended
        if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
            return _invalid("bad strikes")
        if member["strikes"] >= MAX_STRIKES:
            return _invalid("too many strikes")
        fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
        out_status = "reactivated"

    if payment["amount"] < fee:
        return _invalid("insufficient payment")

    return _renewed(member, payment, fee, out_status)

